import struct
from pyspark.sql.datasource import DataSource, DataSourceReader

class TelemetrieBron(DataSource):
    @classmethod
    def name(cls):
        return "telemetrie"
    def schema(self):
        return "meting int, seconde int, snelheid float"
    def reader(self, schema):
        return TelemetrieLezer(self.options)

class TelemetrieLezer(DataSourceReader):
    def __init__(self, options):
        self.pad = options["path"]
    def read(self, partition):
        data = open(self.pad, "rb").read()
        for rec in struct.iter_unpack("<iif", data):  # 12 bytes per meting
            yield (rec[0], rec[1], round(rec[2], 1))

spark.dataSource.register(TelemetrieBron)
spark.read.format("telemetrie").load("vlucht.bin").show()
